`timescale 1ns/1ps
module tb_pulse_stretcher; reg clk=0,rst_n=0,pulse_in=0; wire pulse_out; pulse_stretcher #(.WIDTH(3)) dut(clk,rst_n,pulse_in,pulse_out); always #5 clk=~clk; initial begin #2; rst_n=0; #1; if(pulse_out!==0)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"reset\",\"signal\":\"pulse_out\",\"expected\":0,\"actual\":%0d}",pulse_out); rst_n=1; @(negedge clk); pulse_in=1; @(negedge clk); pulse_in=0; #1; if(pulse_out!==1)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"stretch\",\"signal\":\"pulse_out\",\"expected\":1,\"actual\":%0d}",pulse_out); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"stretch\"}"); repeat(8) @(negedge clk); $finish; end endmodule
